.scope-pill {{ border: 1px solid var(--line); background: var(--panel); border-radius: 999px; padding: clamp(.38rem, .75vw, .6rem) clamp(.6rem, 1.1vw, 1rem); font-family: var(--font-mono); color: var(--ink); font-size: clamp(.58rem, .85vw, .78rem); }}
.planet {{ height: clamp(15rem, 42vw, 31rem); aspect-ratio: 1; border-radius:50%; position:relative; background: radial-gradient(circle at 35% 28%, rgba(240,180,79,.9), rgba(226,107,63,.55) 18%, rgba(70,111,189,.35) 42%, rgba(11,17,24,.2) 69%), radial-gradient(circle at 50% 50%, rgba(93,200,207,.25), transparent 58%); box-shadow: inset clamp(-1.2rem, -3vw, -2.5rem) clamp(-1.2rem, -3vw, -2.5rem) clamp(2rem, 6vw, 5rem) rgba(0,0,0,.55), 0 0 clamp(2rem, 8vw, 6rem) rgba(226,107,63,.26); }}
.planet::before {{ content:''; position:absolute; inset:8%; border: 1px solid rgba(242,239,230,.18); border-radius:50%; transform: rotate(-18deg) scaleX(1.35); }}
.planet::after {{ content:'1750–2024'; position:absolute; right:4%; bottom:13%; font-family:var(--font-mono); color:var(--ink); background:rgba(11,17,24,.72); border:1px solid var(--line); padding:clamp(.45rem,.9vw,.8rem); border-radius:999px; font-size:clamp(.65rem,1vw,.95rem); }}

/* === TIMELINE AND CHARTS === */
.timeline {{ position: relative; height: clamp(13rem, 34vh, 22rem); margin-top: clamp(1rem, 2vw, 2rem); }}
.timeline-line {{ position:absolute; left:4%; right:4%; top:52%; height:2px; background: linear-gradient(90deg, rgba(242,239,230,.25), var(--amber)); }}
.tick {{ position:absolute; top:46%; transform: translateX(-50%); }}
.tick::before {{ content:''; display:block; width:clamp(.55rem,1vw,.9rem); height:clamp(.55rem,1vw,.9rem); border-radius:50%; background:var(--amber); box-shadow:0 0 0 clamp(.22rem,.45vw,.38rem) rgba(240,180,79,.18); margin:auto; }}
.tick span {{ display:block; margin-top:clamp(.5rem,1vw,.8rem); font-family:var(--font-mono); color:var(--muted); font-size:clamp(.55rem,.9vw,.8rem); text-align:center; }}
.tick b {{ display:block; color:var(--ink); font-family:var(--font-body); font-size:clamp(.78rem,1.3vw,1.15rem); }}
.line-chart {{ height: clamp(17rem, 45vh, 28rem); position: relative; border-left: 1px solid var(--line); border-bottom: 1px solid var(--line); margin: clamp(.6rem, 1vw, 1rem) clamp(.4rem, .8vw, .8rem) 0; }}
.line-chart svg {{ position:absolute; inset:0; width:100%; height:100%; overflow:visible; }}
.axis-label {{ position:absolute; font-family:var(--font-mono); font-size:clamp(.48rem,.72vw,.64rem); color:var(--dim); }}
.point-label {{ position:absolute; transform: translate(-50%, -110%); text-align:center; font-family:var(--font-mono); font-size:clamp(.55rem,.85vw,.75rem); color:var(--ink); background:rgba(11,17,24,.78); border:1px solid var(--line); padding:clamp(.25rem,.45vw,.4rem); border-radius:clamp(.35rem,.7vw,.55rem); white-space:nowrap; }}

/* === IMAGE AND COUNTRY TOTALS === */
.figure-frame {{ display:flex; flex-direction:column; gap:clamp(.35rem,.7vw,.6rem); }}
.figure-frame img {{ width:100%; max-height:min(49vh, 420px); object-fit:cover; object-position:center; border-radius:clamp(.7rem,1.3vw,1.1rem); border:1px solid var(--line); filter:saturate(.92) contrast(1.04); }}
.country-bars {{ display:grid; gap:clamp(.38rem,.7vw,.65rem); }}
.country-row {{ display:grid; grid-template-columns: clamp(4.2rem, 8.5vw, 7rem) 1fr clamp(3.2rem, 5vw, 4.5rem); gap:clamp(.45rem,.8vw,.7rem); align-items:center; }}
.country-row .name {{ color:var(--muted); font-weight:600; font-size:clamp(.72rem,1.05vw,.95rem); }}
.bar-track {{ height:clamp(.55rem,1vw,.9rem); background:rgba(255,255,255,.08); border-radius:999px; overflow:hidden; }}
.bar-fill {{ height:100%; border-radius:999px; background:linear-gradient(90deg,var(--cyan),var(--amber),var(--orange)); }}
.value {{ font-family:var(--font-mono); color:var(--ink); font-size:clamp(.58rem,.82vw,.76rem); text-align:right; }}

/* === SHARE SHIFT === */
.share-grid {{ display:grid; grid-template-columns:1fr 1fr; gap:clamp(1rem,2vw,1.8rem); }}
.share-card h3 {{ font-family:var(--font-display); font-size:clamp(1.4rem,3vw,3rem); margin:0 0 clamp(.55rem,1vw,.9rem); }}
.stacked {{ height: clamp(3.6rem, 8vh, 5.4rem); border-radius:clamp(.6rem,1vw,.9rem); overflow:hidden; display:flex; border:1px solid var(--line); margin:clamp(.6rem,1vw,1rem) 0; }}
.seg {{ height:100%; display:flex; align-items:center; justify-content:center; font-family:var(--font-mono); font-size:clamp(.52rem,.78vw,.7rem); color:#081018; font-weight:600; min-width:clamp(.18rem,.3vw,.3rem); }}
.legend {{ display:grid; gap:clamp(.35rem,.6vw,.5rem); margin-top:clamp(.5rem,1vw,.8rem); }}
.legend div {{ display:flex; align-items:center; gap:clamp(.4rem,.8vw,.7rem); color:var(--muted); font-size:clamp(.72rem,1.05vw,.95rem); }}
.swatch {{ width:clamp(.7rem,1vw,.9rem); height:clamp(.7rem,1vw,.9rem); border-radius:.2rem; flex:0 0 auto; }}

/* === PER CAPITA === */
.percap-layout {{ display:grid; grid-template-columns:minmax(0, 1.25fr) minmax(0,.75fr); gap:clamp(1rem,2.6vw,2.6rem); align-items:center; }}
.hbar-list {{ display:grid; gap:clamp(.35rem,.65vw,.56rem); }}
.hbar-row {{ display:grid; grid-template-columns: clamp(5rem, 10vw, 8.5rem) 1fr clamp(3.4rem,5vw,4.8rem); gap:clamp(.45rem,.8vw,.7rem); align-items:center; }}
.hbar-row .label {{ color:var(--muted); font-weight:600; font-size:clamp(.72rem,1.05vw,.95rem); }}
.hbar {{ height:clamp(.72rem,1.35vw,1.1rem); background:rgba(255,255,255,.08); border-radius:999px; overflow:hidden; }}
.hbar span {{ display:block; height:100%; border-radius:999px; background:linear-gradient(90deg,#79a6ff,var(--cyan),var(--amber),var(--orange)); }}
.disparity {{ border-left: clamp(.25rem,.5vw,.42rem) solid var(--orange); padding-left:clamp(.75rem,1.4vw,1.2rem); }}
.disparity .big {{ font-family:var(--font-display); font-size:clamp(2.5rem,7vw,6.8rem); line-height:.8; color:var(--orange); letter-spacing:-.06em; }}

/* === MAP AND TABLE === */
.map-layout {{ display:grid; grid-template-columns:minmax(0,1.08fr) minmax(0,.92fr); gap:clamp(1rem,2.5vw,2.3rem); align-items:center; }}
.map-layout img {{ width:100%; max-height:min(58vh, 500px); object-fit:contain; border-radius:clamp(.8rem,1.4vw,1.2rem); border:1px solid var(--line); background:#f6f2e8; }}
.callouts {{ display:grid; gap:clamp(.6rem,1vw,.9rem); }}
.callout {{ display:grid; grid-template-columns: clamp(.35rem,.6vw,.5rem) 1fr; gap:clamp(.55rem,1vw,.8rem); align-items:start; background:var(--panel); border:1px solid var(--line); border-radius:clamp(.6rem,1vw,.9rem); padding:clamp(.65rem,1.2vw,1rem); }}
.callout i {{ display:block; width:100%; height:100%; min-height:clamp(2rem,4vw,3rem); border-radius:999px; }}
table {{ width:100%; border-collapse:collapse; overflow:hidden; border-radius:clamp(.7rem,1.2vw,1rem); font-size:clamp(.72rem,1vw,.95rem); }}
th, td {{ border-bottom:1px solid var(--line); padding:clamp(.5rem,.9vw,.8rem); text-align:left; vertical-align:top; }}
th {{ color:var(--cyan); font-family:var(--font-mono); text-transform:uppercase; letter-spacing:.08em; font-size:clamp(.52rem,.78vw,.7rem); }}
td {{ color:var(--muted); }}
td:first-child {{ color:var(--ink); font-weight:700; }}
.takeaways {{ display:grid; grid-template-columns:repeat(5,1fr); gap:clamp(.55rem,1vw,.9rem); margin-top:clamp(1rem,2vw,1.7rem); }}
.takeaway {{ min-height:clamp(9rem,26vh,16rem); display:flex; flex-direction:column; justify-content:space-between; background:linear-gradient(180deg,var(--panel-strong),rgba(255,255,255,.035)); border:1px solid var(--line); border-radius:clamp(.7rem,1.2vw,1rem); padding:clamp(.7rem,1.3vw,1.1rem); }}
.takeaway b {{ font-family:var(--font-display); font-size:clamp(1.3rem,3.3vw,3.2rem); line-height:.88; color:var(--amber); }}
.takeaway span {{ color:var(--muted); font-size:clamp(.7rem,1.05vw,.98rem); line-height:1.2; }}

/* === RESPONSIVE DENSITY === */
@media (max-height: 700px) {{
  .content-grid, .percap-layout, .map-layout {{ gap: clamp(.7rem, 1.6vw, 1.4rem); }}
  .panel {{ padding: clamp(.55rem, 1vw, 1rem); }}
  .figure-frame img {{ max-height: min(42vh, 330px); }}
  .takeaway {{ min-height: clamp(7rem, 23vh, 12rem); }}
}}
@media (max-height: 600px) {{
  .slide {{ padding: clamp(.75rem, 2.2vw, 1.8rem); }}
  .figure-frame img, .map-layout img {{ max-height: min(40vh, 280px); }}
  .timeline, .line-chart {{ height: clamp(10rem, 34vh, 16rem); }}
}}
@media (max-height: 500px) {{
  .title-wrap, .content-grid, .percap-layout, .map-layout {{ grid-template-columns: 1fr 1fr; }}
  .takeaways {{ gap: clamp(.35rem, .7vw, .6rem); }}
}}
@media (prefers-reduced-motion: reduce) {{ .reveal {{ transition: none !important; opacity: 1 !important; transform: none !important; }} }}
</style>
</head>
<body>
<main>
  <!-- === SLIDE 1: TITLE === -->
  <section class="slide title-slide visible" data-slide="1">
    <div class="title-wrap">
      <div>
        <div class="kicker reveal">Policy briefing deck · NASA + Global Carbon Budget 2025</div>
        <h1 class="reveal">Global CO₂ Emissions</h1>
        <p class="title-sub reveal">Trends, regional shifts, and per-capita inequalities from the Industrial Revolution to 2024.</p>
        <div class="scope-band reveal"><span class="scope-pill">Scope: 1750–2024</span><span class="scope-pill">Audience: climate negotiators</span><span class="scope-pill">Lens: totals + equity</span></div>
      </div>
      <div class="planet reveal" aria-hidden="true"></div>
    </div>
    <div class="source">Source: NASA CO₂ vital signs; Our World in Data / Global Carbon Budget 2025</div><div class="slide-no">01 / 09</div>
  </section>

  <!-- === SLIDE 2: ATMOSPHERIC CO2 === -->
  <section class="slide" data-slide="2">
    <div class="content-grid">
      <div>
        <div class="kicker reveal">Atmospheric concentration</div>
        <h2 class="reveal">CO₂ reaches <span class="accent">429 ppm</span> — over 50% above pre‑industrial levels</h2>
        <p class="reveal">NOAA’s Mauna Loa Observatory recorded 429 ppm in February 2026, compared with a pre‑industrial baseline of approximately 280 ppm.</p>
      </div>
      <div class="panel reveal">
        <div class="stat">429</div><div class="stat-label">parts per million · February 2026</div>
        <div class="timeline">
          <div class="timeline-line"></div>
          <div class="tick" style="left:9%"><span><b>~280 ppm</b>Pre‑industrial</span></div>
          <div class="tick" style="left:43%"><span><b>1958</b>Mauna Loa record begins</span></div>
          <div class="tick" style="left:91%"><span><b>429 ppm</b>Feb 2026</span></div>
        </div>
        <p class="note">The current level is at least 1.5× greater than the natural increase at the end of the last ice age; that prior shift unfolded over thousands of years, while this change occurred in roughly two centuries.</p>
      </div>
    </div>
    <div class="source">Ground and satellite measurements link the acceleration primarily to coal, oil, and natural gas combustion.</div><div class="slide-no">02 / 09</div>
  </section>

  <!-- === SLIDE 3: GLOBAL EMISSIONS TRAJECTORY === -->
  <section class="slide" data-slide="3">
    <div class="content-grid">
      <div>
        <div class="kicker reveal">Global emissions trajectory</div>
        <h2 class="reveal">Fossil fuel CO₂ grew from <span class="accent">6 Bt</span> in 1950 to <span class="accent">35+ Bt</span> today</h2>
        <p class="reveal">Emissions were negligible before the Industrial Revolution, grew slowly until the mid‑20th century, nearly quadrupled by 1990, and have not yet peaked.</p>
      </div>
      <div class="panel reveal">
        <div class="line-chart" role="img" aria-label="Line chart showing global emissions rising from near zero to 6 billion tonnes in 1950, over 20 billion tonnes in 1990, and above 35 billion tonnes today.">
          <svg viewBox="0 0 100 100" preserveAspectRatio="none">
            <defs><linearGradient id="growth" x1="0" x2="1"><stop offset="0" stop-color="#5dc8cf"/><stop offset=".55" stop-color="#f0b44f"/><stop offset="1" stop-color="#e26b3f"/></linearGradient></defs>
            <path d="M3 92 C18 91 27 90 39 84 C50 77 57 63 66 45 C75 29 86 18 97 11" fill="none" stroke="url(#growth)" stroke-width="3.5" stroke-linecap="round"/>
            <path d="M3 92 C18 91 27 90 39 84 C50 77 57 63 66 45 C75 29 86 18 97 11 L97 100 L3 100 Z" fill="rgba(240,180,79,.12)"/>
          </svg>
          <div class="axis-label" style="left:0;bottom:-1.7em">1750</div><div class="axis-label" style="left:37%;bottom:-1.7em">1950</div><div class="axis-label" style="left:64%;bottom:-1.7em">1990</div><div class="axis-label" style="right:0;bottom:-1.7em">2024</div>
          <div class="point-label" style="left:39%;top:77%">1950<br>~6 Bt</div><div class="point-label" style="left:66%;top:39%">1990<br>20+ Bt</div><div class="point-label" style="left:96%;top:6%">Today<br>35+ Bt</div>
        </div>
        <p class="note">Figure reference requested for this trajectory; no `figure_2.jpg` asset was provided, so the chart uses only values stated in the source brief.</p>
      </div>
    </div>
    <div class="source">Bt = billion tonnes CO₂ from fossil fuels and industry.</div><div class="slide-no">03 / 09</div>
  </section>

  <!-- === SLIDE 4: COUNTRY TOTALS === -->
  <section class="slide" data-slide="4">
    <div class="content-grid">
      <div>
        <div class="kicker reveal">Country-level totals</div>
        <h2 class="reveal">China emits <span class="accent">~12.5 Bt</span> — more than double the United States</h2>
        <div class="panel reveal country-bars">
          <div class="country-row"><div class="name">China</div><div class="bar-track"><div class="bar-fill" style="width:100%"></div></div><div class="value">~12.5 Bt</div></div>
          <div class="country-row"><div class="name">United States</div><div class="bar-track"><div class="bar-fill" style="width:40%"></div></div><div class="value">~5.0</div></div>
          <div class="country-row"><div class="name">India</div><div class="bar-track"><div class="bar-fill" style="width:24%"></div></div><div class="value">~3.0</div></div>
          <div class="country-row"><div class="name">EU‑27</div><div class="bar-track"><div class="bar-fill" style="width:22%"></div></div><div class="value">~2.7</div></div>
          <div class="country-row"><div class="name">Germany</div><div class="bar-track"><div class="bar-fill" style="width:5%"></div></div><div class="value">~0.6</div></div>
          <div class="country-row"><div class="name">Brazil</div><div class="bar-track"><div class="bar-fill" style="width:4%"></div></div><div class="value">~0.5</div></div>
          <div class="country-row"><div class="name">UK / France</div><div class="bar-track"><div class="bar-fill" style="width:2.4%"></div></div><div class="value">~0.3</div></div>
        </div>
      </div>
      <div class="figure-frame reveal"><img src="{imgs['figure_3.jpg']}" alt="Annual CO₂ emissions by country"><p class="note">Reference: figure_3.jpg. China accounts for ~27% of global emissions; the US is ~14% and declining from its ~6 Bt peak around 2005.</p></div>
    </div>
    <div class="source">Annual CO₂, approximate billion tonnes and global shares from source brief.</div><div class="slide-no">04 / 09</div>
  </section>

  <!-- === SLIDE 5: REGIONAL SHARE SHIFT === -->
  <section class="slide" data-slide="5">
    <div>
      <div class="kicker reveal">Regional share shift</div>
      <h2 class="reveal">Asia now produces <span class="accent">~50%</span>; US + Europe are below one‑third</h2>
      <div class="share-grid reveal">
        <div class="panel share-card">
          <h3>1900</h3>
          <p>Europe and the US accounted for <strong>more than 90%</strong> of global emissions.</p>
          <div class="stacked"><div class="seg" style="width:92%;background:#f0b44f">Europe + US &gt;90%</div><div class="seg" style="width:8%;background:#5dc8cf"></div></div>
          <div class="legend"><div><span class="swatch" style="background:#f0b44f"></span>Industrial-era concentration in Europe + US</div><div><span class="swatch" style="background:#5dc8cf"></span>All other regions: small remainder</div></div>
        </div>
        <div class="panel share-card">
          <h3>2024</h3>
          <p>Asia produces roughly <strong>half</strong>; US + Europe are <strong>below one‑third</strong>.</p>
          <div class="stacked"><div class="seg" style="width:50%;background:#e26b3f">Asia ~50%</div><div class="seg" style="width:31%;background:#466fbd;color:#fff">US+Europe &lt;33%</div><div class="seg" style="width:4%;background:#7aae78"></div><div class="seg" style="width:4%;background:#9a82d8"></div><div class="seg" style="width:11%;background:#5dc8cf"></div></div>
          <div class="legend"><div><span class="swatch" style="background:#e26b3f"></span>Asia: roughly half of all emissions</div><div><span class="swatch" style="background:#466fbd"></span>US + Europe: below one-third combined</div><div><span class="swatch" style="background:#7aae78"></span>Africa: 3–4%; South America: 3–4%</div></div>
        </div>
      </div>
      <p class="note reveal">The visual is a side-by-side comparison of known source shares; it communicates the dramatic re-centering of annual emissions from historic industrial economies toward Asia.</p>
    </div>
    <div class="source">By 1950, Europe and the US still represented over 85%; today Africa and South America each contribute only 3–4%.</div><div class="slide-no">05 / 09</div>
  </section>

  <!-- === SLIDE 6: PER CAPITA === -->
  <section class="slide" data-slide="6">
    <div class="percap-layout">
      <div>
        <div class="kicker reveal">Per-capita inequalities</div>
        <h2 class="reveal">Per capita gap: <span class="accent">15 t</span> in the US vs. <span class="accent">0.1 t</span> in Chad</h2>
        <div class="panel reveal hbar-list">
          <div class="hbar-row"><div class="label">United States</div><div class="hbar"><span style="width:100%"></span></div><div class="value">~15 t</div></div>
          <div class="hbar-row"><div class="label">Canada</div><div class="hbar"><span style="width:87%"></span></div><div class="value">~13</div></div>
          <div class="hbar-row"><div class="label">China</div><div class="hbar"><span style="width:60%"></span></div><div class="value">~9</div></div>
          <div class="hbar-row"><div class="label">EU‑27</div><div class="hbar"><span style="width:47%"></span></div><div class="value">~7</div></div>
          <div class="hbar-row"><div class="label">World avg.</div><div class="hbar"><span style="width:33%"></span></div><div class="value">~5</div></div>
          <div class="hbar-row"><div class="label">United Kingdom</div><div class="hbar"><span style="width:27%"></span></div><div class="value">~4</div></div>
          <div class="hbar-row"><div class="label">India</div><div class="hbar"><span style="width:13%"></span></div><div class="value">~2</div></div>
          <div class="hbar-row"><div class="label">Kenya</div><div class="hbar"><span style="width:5%"></span></div><div class="value">&lt;1</div></div>
          <div class="hbar-row"><div class="label">Chad / Niger</div><div class="hbar"><span style="width:.7%"></span></div><div class="value">~0.1</div></div>
        </div>
      </div>
      <div class="panel reveal disparity">
        <div class="big">150×</div>
        <p>The average American or Australian emits in under two days what the average person in Chad or Niger emits in an entire year.</p>
        <div class="figure-frame"><img src="{imgs['figure_1.jpg']}" alt="Per capita CO₂ emissions over time"><p class="note">Reference: figure_1.jpg.</p></div>
      </div>
    </div>
    <div class="source">Tonnes CO₂ per person per year; selected countries from source brief.</div><div class="slide-no">06 / 09</div>
  </section>

  <!-- === SLIDE 7: 2024 CHANGE MAP === -->
  <section class="slide" data-slide="7">
    <div class="map-layout">
      <div class="figure-frame reveal"><img src="{imgs['figure_4.jpg']}" alt="Annual percentage change in CO₂ emissions, 2024"><p class="note">Reference: figure_4.jpg — annual percentage change in CO₂ emissions, 2024.</p></div>
      <div>
        <div class="kicker reveal">Annual change snapshot</div>
        <h2 class="reveal">2024 shows a mixed map of cuts and increases</h2>
        <div class="callouts reveal">
          <div class="callout"><i style="background:#466fbd"></i><p><strong class="blue">Declines:</strong> the United States and much of Europe recorded roughly −1% to −5%, shown in blue.</p></div>
          <div class="callout"><i style="background:#e26b3f"></i><p><strong class="orange">Increases:</strong> Russia, parts of Southeast Asia, and several African nations rose by +2% to +10% or more.</p></div>
          <div class="callout"><i style="background:#d85b4e"></i><p><strong>Outliers:</strong> one or two South American countries experienced very large percentage increases above +10%, while others declined.</p></div>
        </div>
      </div>
    </div>
    <div class="source">Map colors and ranges follow the source brief description.</div><div class="slide-no">07 / 09</div>
  </section>

  <!-- === SLIDE 8: ENERGY MIX === -->
  <section class="slide" data-slide="8">
    <div class="content-grid">
      <div>
        <div class="kicker reveal">Energy mix and policy choices</div>
        <h2 class="reveal">Similar prosperity can yield very different per‑capita CO₂</h2>
        <p class="reveal">France and the UK have much lower per capita emissions than Germany or the Netherlands, largely because of their energy mix: higher nuclear and renewable shares versus higher fossil fuel reliance.</p>
      </div>
      <div class="panel reveal">
        <table>
          <thead><tr><th>Country group</th><th>Energy sources highlighted</th><th>Per capita CO₂</th></tr></thead>
          <tbody>
            <tr><td>France / UK</td><td>Higher nuclear and renewable shares; declining emissions</td><td>France ~4 t; UK ~4 t</td></tr>
            <tr><td>Germany / Netherlands</td><td>Higher fossil fuel share than France / UK</td><td>Higher than France / UK</td></tr>
          </tbody>
        </table>
        <p class="note" style="margin-top:clamp(.7rem,1.2vw,1rem)">Source brief provides explicit per-capita values for France and the UK and a directional contrast for Germany / Netherlands; no unsupported exact values are added.</p>
      </div>
    </div>
    <div class="source">Policy implication: energy-system composition, not only income, shapes per-person emissions outcomes.</div><div class="slide-no">08 / 09</div>
  </section>

  <!-- === SLIDE 9: TAKEAWAYS === -->
  <section class="slide" data-slide="9">
    <div>
      <div class="kicker reveal">Synthesis for negotiators</div>
      <h2 class="reveal">Emissions are still rising, but the map of responsibility is shifting</h2>
      <div class="takeaways reveal">
